def tag_clean(n: Any) -> object {
    if (n[0] in "-~!") {
        return n[1:];
    }
    return n;
}

"""
    Convert YeT extension in filename to .tex

    :param filename: string of file name. validity not checked.
    :param extensions: tuple of extensions (without dot) to treat as YeT
    """
def convert_extension(filename: Any, extensions: Any = ('yaml', 'yml')) -> object {
    if ('.' in filename) {
        ext = filename.split('.')[-1];
        if (ext in extensions) {
            idx = filename.rindex('.');
            return f'{filename[:idx]}.tex';
        }
    }
    return f'{filename}.tex';
}

"""
    Calculate list of precision and recall values from lists of true pos.,
    false pos., false neg. values.
    """
def calculate_precision_recall(
    tp_totals: Any, fp_totals: Any, fn_totals: Any
) -> object {
    precision = [
        (tp / (tp + fp)) if ((tp + fp) > 0) else 0
        for (tp, fp) in zip(tp_totals, fp_totals)
    ];
    recall = [
        (tp / (tp + fn)) if ((tp + fn) > 0) else 0
        for (tp, fn) in zip(tp_totals, fn_totals)
    ];
    return (precision, recall);
}

"""
    Round income to the lower 10000th
    Intput:
    - income
    Output:
    - lower 10000th of the income. Return 0 if the income
    is less than 30,000 or more than 120,000
    """
def round_income(x: Any) -> object {
    for y in range(30, 130, 10) {
        if ((x >= (y * 1000)) and (x < ((y + 10) * 1000))) {
            return (y * 1000);
        }
    }
    return 0;
}
